tool_input.command:
cat > tests/Debug.test.ts <<'EOF'
import { it } from 'bun:test'
import { TestApp } from '@guren/testing'
import { getDatabase, resetDatabase } from '../config/database.js'
import app from '../src/app.js'
import { User } from '../app/Models/User.js'
import { posts, postTags, tags } from '../db/schema.js'
it('debug', async () => {
  await resetDatabase()
  const http = await TestApp.fromApp(app)
  const author = await User.create({ name: 'A', email: 'a@example.com', password: 'secret' })
  const csrf = await http.actingAs(author).withCsrf()
  const res = await csrf.json().post('/posts', { title: 't', excerpt: 'e', body: 'b', tags: 'bun, webdev' })
  console.log('STATUS', res.status, res.headers.get('location'))
  const db = await getDatabase()
  console.log('POSTS', await db.select().from(posts))
  console.log('TAGS', await db.select().from(tags))
  console.log('PT', await db.select().from(postTags))
})
EOF
bun test tests/Debug.test.ts 2>&1 | head -60
